// Match only unambiguous exact titles; never use popularity as identity evidence.
const normalizeTitle = s => String(s||'').normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');
function chooseCandidate(record,data){
 const title=normalizeTitle(record.title),year=(record.meta||'').match(/((?:19|20)\d{2})年製作/)?.[1];
 if(data.total_pages>1)return {reason:'候補が多いため要確認'};
 const exact=(data.results||[]).filter(m=>[m.title,m.original_title].some(t=>normalizeTitle(t)===title));
 const candidates=year?exact.filter(m=>m.release_date?.slice(0,4)===year):exact;
 if(candidates.length!==1)return {reason:candidates.length>1?'同名作品の候補が複数':'作品名・公開年の完全一致なし'};
 if(!year&&title.length<=3)return {reason:'短い作品名・公開年なしのため要確認'};
 return {candidate:candidates[0],evidence:year?'作品名と製作年が完全一致':'作品名が完全一致・全検索結果内で候補が1件'};
}
const txt=v=>typeof v==='string'?v:'';
function metadata(data){
 const now=Date.now(),jp=data['watch/providers']?.results?.JP,groups={};
 for(const k of ['flatrate','rent','buy','free','ads'])groups[k]=[...new Set((jp?.[k]||[]).map(p=>txt(p.provider_name)).filter(Boolean))];
 const dates=(data.release_dates?.results||[]).find(r=>r.iso_3166_1==='JP')?.release_dates||[];
 return {source:'TMDB',id:data.id,title:txt(data.title),originalTitle:txt(data.original_title),releaseDate:txt(data.release_date),japanTheatricalDate:dates.filter(r=>[2,3].includes(r.type)).map(r=>r.release_date.slice(0,10)).sort()[0]||'',runtime:data.runtime||null,directors:(data.credits?.crew||[]).filter(p=>p.job==='Director').map(p=>txt(p.name)),cast:(data.credits?.cast||[]).slice(0,12).map(p=>({name:txt(p.name),character:txt(p.character)})),genres:(data.genres||[]).map(g=>txt(g.name)),overview:txt(data.overview),poster:/^\/[\w.-]+$/.test(data.poster_path||'')?'https://image.tmdb.org/t/p/w500'+data.poster_path:'',checkedAt:now,providers:data['watch/providers']?{...groups,checkedAt:now,region:'JP',link:txt(jp?.link)}:null,providerError:!data['watch/providers']};
}
const protectedRecord = record => {const {movie,enrichment,_revision,...rest}=record;return rest;};
async function enrichBatch(request,env){
 const url=new URL(request.url);
 if(request.method==='GET'){
  const {results}=await env.DB.prepare('SELECT f.id,f.body,s.body AS original FROM films f LEFT JOIN enrichment_snapshots s ON f.id=s.id').all();
  let linked=0,review=0,errors=0,posters=0,protectedMismatch=0,processed=0;
  for(const row of results){const r=JSON.parse(row.body);if(r.enrichment){processed++;if(r.enrichment.status==='linked')linked++;else if(r.enrichment.status==='review')review++;else errors++;}if(r.movie?.poster)posters++;if(row.original){const o=JSON.parse(row.original),core=x=>JSON.stringify([x.title,x.status,x.rating,x.review,x.meta]);/* Only records the owner has not edited since the snapshot; enrichment never changes updated. */if(o.updated===r.updated&&core(r)!==core(o))protectedMismatch++;}}
  return json({total:results.length,processed,linked,review,errors,posters,protectedMismatch});
 }
 if(request.method!=='POST')return json({error:'利用できません。'},405);
 const input=await request.json(),cursor=typeof input.cursor==='string'?input.cursor:'';
 const {results}=await env.DB.prepare('SELECT id,body,revision FROM films WHERE id > ? ORDER BY id LIMIT 5').bind(cursor).all();
 const key=await storedKey(env);if(!key)return json({error:'映画情報の共通接続が必要です。'},503);
 const outcomes=await Promise.all(results.map(async row=>{
  const record=JSON.parse(row.body);
  if(record.enrichment||record.movie?.id)return {id:row.id,status:'skip'};
  try{
   const search=await upstream('search/movie',key,[['query',record.title],['include_adult','false'],['region','JP']]);if(!search.ok)throw new Error('search');
   const data=await search.json(),match=chooseCandidate(record,data);let movie;
   if(match.candidate){const detail=await upstream('movie/'+match.candidate.id,key,[['append_to_response','credits,release_dates,watch/providers']]);if(!detail.ok)throw new Error('details');const d=await detail.json();if(d.id!==match.candidate.id)throw new Error('identity');movie=metadata(d);}
   const enrichment={status:movie?'linked':'review',reason:match.evidence||match.reason,checkedAt:Date.now(),candidates:movie?[]:(data.results||[]).filter(m=>normalizeTitle(m.title)===normalizeTitle(record.title)||normalizeTitle(m.original_title)===normalizeTitle(record.title)).slice(0,6).map(m=>({id:m.id,title:m.title,year:(m.release_date||'').slice(0,4)}))};
   const next={...record,...(movie?{movie}:{}),enrichment};
   // The snapshot and optimistic update are one transaction. Concurrent edits win.
   const saved=await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO enrichment_snapshots(id,body,revision) VALUES(?,?,?)').bind(row.id,row.body,row.revision),env.DB.prepare('UPDATE films SET body=?,revision=revision+1 WHERE id=? AND revision=?').bind(JSON.stringify(next),row.id,row.revision)]);
   return {id:row.id,status:saved[1].meta.changes===1?enrichment.status:'conflict'};
  }catch{return {id:row.id,status:'error'};}
 }));
 return json({cursor:results.at(-1)?.id||cursor,done:results.length<5,outcomes});
}

// Passphrase gate for the Cloudflare deployment (added at migration time).
// The app itself still checks for the ChatGPT Sites identity header; after a
// successful passphrase login this gate injects that header, so worker/api.mjs
// and the client stay unchanged. Active only when both AUTH_SECRET and
// AUTH_PASSPHRASE are set as Worker secrets; otherwise it is skipped.
async function yoinAuthToken(env) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(env.AUTH_SECRET), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('yoin-owner-v1'));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
}
function yoinCookieValue(request, name) {
  const raw = request.headers.get('Cookie') || '';
  for (const part of raw.split(';')) {
    const i = part.indexOf('=');
    if (i > 0 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return '';
}
function yoinSame(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function yoinLoginPage(error) {
  return `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>余韻 — ログイン</title><style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f6f3ec;font-family:sans-serif;color:#223}.card{background:#fff;border:1px solid #ddd6c4;border-radius:16px;padding:32px 28px;max-width:340px;width:88%;box-shadow:0 8px 30px rgba(60,50,20,.08)}h1{font-size:28px;margin:0 0 4px;letter-spacing:.2em}.sub{color:#667;font-size:13px;margin:0 0 20px}label{font-size:13px;color:#445;display:block;margin-bottom:6px}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #c9c2ae;border-radius:10px;font-size:16px}button{margin-top:16px;width:100%;padding:12px;border:0;border-radius:10px;background:#20503c;color:#fff;font-size:16px;cursor:pointer}.err{color:#a33;font-size:13px;margin:0 0 12px}</style></head><body><main class="card"><h1>余韻</h1><p class="sub">映画の記録 — 本人専用です</p>${error ? '<p class="err">合言葉が違います。もう一度お試しください。</p>' : ''}<form method="post" action="/login"><label for="p">合言葉</label><input id="p" name="passphrase" type="password" autocomplete="current-password" required autofocus><button type="submit">開く</button></form></main></body></html>`;
}
async function yoinGate(request, env, path) {
  if (path === '/login') {
    if (request.method === 'POST') {
      const form = await request.formData().catch(() => null);
      const pass = form ? String(form.get('passphrase') || '') : '';
      if (yoinSame(pass, env.AUTH_PASSPHRASE)) {
        const token = await yoinAuthToken(env);
        return new Response(null, { status: 303, headers: { 'Location': '/', 'Set-Cookie': 'yoin_auth=' + token + '; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=15552000', 'Cache-Control': 'no-store' } });
      }
      return new Response(yoinLoginPage(true), { status: 401, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
    }
    return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
  }
  if (path === '/logout') {
    return new Response(null, { status: 303, headers: { 'Location': '/login', 'Set-Cookie': 'yoin_auth=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0', 'Cache-Control': 'no-store' } });
  }
  // /api/bot/* is authenticated by its own bearer token inside botApi() (worker/bot-api.mjs),
  // never by the cookie; the bearer token is not accepted anywhere else.
  if (path.startsWith('/api/bot/')) return request;
  const token = await yoinAuthToken(env);
  if (yoinSame(yoinCookieValue(request, 'yoin_auth'), token)) {
    const headers = new Headers(request.headers);
    headers.set('oai-authenticated-user-id', 'owner');
    return new Request(request, { headers });
  }
  if (path.startsWith('/api/')) return Response.json({ error: 'ログインが必要です。ページを開き直してログインしてください。' }, { status: 401, headers: { 'Cache-Control': 'no-store' } });
  return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}

// Scoped API for the owner's chat bot (/api/bot/*).
// Authenticated ONLY by `Authorization: Bearer <BOT_API_TOKEN>` (Worker secret).
// The token is never accepted on any other path, and this API can only search,
// list, create and partially update records — no delete, import, TMDB
// connection or enrichment. Created records use the same shape as the UI.
const BOT_FIELDS = ['status', 'rating', 'date', 'review', 'meta', 'spoiler', 'method', 'service', 'viewings'];
const botJson = (data, status = 200) => Response.json(data, {status, headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function botAuthorized(request, env) {
  const token = typeof env.BOT_API_TOKEN === 'string' ? env.BOT_API_TOKEN : '';
  if (token.length < 32) return 'unconfigured';
  const header = request.headers.get('Authorization') || '';
  const m = /^Bearer\s+(\S+)$/.exec(header);
  return m && yoinSame(m[1], token) ? 'ok' : 'denied';
}
// Same rules as client/app.js validateRecords(), so bot records never break the UI.
function botClientValid(r) {
  if (!validate(r) || Math.abs(r.rating * 10 - Math.round(r.rating * 10)) > 0.000001) return false;
  const m = r.movie;
  if (m != null) {
    if (m.source !== 'TMDB' || !Number.isInteger(m.id) || m.id < 1 || (m.mediaType != null && !['movie', 'tv'].includes(m.mediaType)) || (m.seasons != null && !Number.isInteger(m.seasons)) || (m.episodes != null && !Number.isInteger(m.episodes)) || ['title', 'originalTitle', 'releaseDate', 'japanTheatricalDate', 'overview', 'poster'].some(k => typeof m[k] !== 'string') || !Number.isFinite(m.checkedAt) || !Array.isArray(m.directors) || !Array.isArray(m.genres) || [...m.directors, ...m.genres].some(x => typeof x !== 'string')) return false;
    if (m.cast != null && (!Array.isArray(m.cast) || m.cast.some(p => !p || typeof p.name !== 'string' || typeof p.character !== 'string'))) return false;
    if (m.providers != null) {
      const p = m.providers;
      if (p.region !== 'JP' || !Number.isFinite(p.checkedAt) || typeof p.link !== 'string' || ['flatrate', 'rent', 'buy', 'free', 'ads'].some(k => !Array.isArray(p[k]) || p[k].some(x => typeof x !== 'string'))) return false;
    }
  }
  return true;
}
// Field checks for bot input. Returns an error message or ''.
function botFieldError(data) {
  if ('status' in data && !['watched', 'want'].includes(data.status)) return 'status は "watched" か "want" を指定してください。';
  if ('rating' in data && (typeof data.rating !== 'number' || !Number.isFinite(data.rating) || data.rating < 0 || data.rating > 5 || Math.abs(data.rating * 10 - Math.round(data.rating * 10)) > 0.000001)) return 'rating は 0〜5 の数値（小数第1位まで、0 は未評価）で指定してください。';
  if ('date' in data && (typeof data.date !== 'string' || (data.date !== '' && !PARTIAL_DATE.test(data.date)))) return 'date は "YYYY-MM-DD"・"YYYY-MM"（月まで）・"YYYY"（年だけ）か空文字で指定してください。';
  for (const k of ['review', 'meta']) if (k in data && (typeof data[k] !== 'string' || data[k].length > 100000)) return k + ' は文字列で指定してください。';
  return extrasError(data);
}
const botDate = v => /^\d{4}-\d{2}-\d{2}/.test(v || '') ? v.slice(0, 10) : '';
const botText = v => typeof v === 'string' ? v : '';
const botImage = p => /^\/[a-zA-Z0-9_.-]+$/.test(p || '') ? 'https://image.tmdb.org/t/p/w500' + p : '';
const botNormalize = s => String(s || '').normalize('NFKC').replace(/\s+/g, '').toLowerCase();
class BotTmdbError extends Error { constructor(status, message) { super(message); this.status = status; } }
async function botTmdb(env, key, path, params = []) {
  let result;
  try { result = await upstream(path, key, params); } catch { throw new BotTmdbError(503, '映画情報に接続できませんでした。時間をおいて再度お試しください。'); }
  if (result.status === 404) throw new BotTmdbError(404, 'TMDBに該当する作品がありません。');
  if (!result.ok) throw new BotTmdbError(result.status === 429 ? 429 : 502, result.status === 429 ? '検索が混み合っています。少し待って再度お試しください。' : '映画情報を取得できませんでした。');
  return result.json();
}
async function botKey(env) {
  if (!env.TMDB_CONFIG_KEY) throw new BotTmdbError(503, '共通接続を準備しています。');
  const key = await storedKey(env);
  if (!key) throw new BotTmdbError(503, '映画情報を接続してください。');
  return key;
}
// Port of FilmAPI.normalizeProviders / FilmAPI.details in client/films-api.js.
function botProviders(data, checkedAt, media) {
  const jp = data.results?.JP, groups = {};
  for (const k of ['flatrate', 'rent', 'buy', 'free', 'ads']) groups[k] = [...new Set((jp?.[k] || []).map(p => botText(p.provider_name)).filter(Boolean))];
  const linkPattern = media === 'tv' ? /^https:\/\/www\.themoviedb\.org\/tv\// : /^https:\/\/www\.themoviedb\.org\/movie\//;
  return { ...groups, checkedAt, region: 'JP', link: linkPattern.test(jp?.link || '') ? jp.link : '' };
}
async function botDetails(env, key, id, media) {
  const [result, providers] = await Promise.allSettled([
    botTmdb(env, key, media + '/' + id, [['append_to_response', media === 'tv' ? 'credits' : 'credits,release_dates']]),
    botTmdb(env, key, media + '/' + id + '/watch/providers')
  ]);
  if (result.status !== 'fulfilled') throw result.reason;
  const data = result.value, now = Date.now();
  if (data.id !== id) throw new BotTmdbError(502, '映画情報を取得できませんでした。');
  const normalized = providers.status === 'fulfilled' ? botProviders(providers.value, now, media) : null;
  const cast = (data.credits?.cast || []).slice(0, 12).map(p => ({ name: botText(p.name), character: botText(p.character) }));
  const genres = (data.genres || []).map(g => botText(g.name)).filter(Boolean);
  if (media === 'tv') {
    const runTimes = (data.episode_run_time || []).filter(t => Number.isFinite(t) && t > 0);
    return {
      source: 'TMDB', id, mediaType: 'tv', title: botText(data.name), originalTitle: botText(data.original_name),
      releaseDate: botDate(data.first_air_date), japanTheatricalDate: '',
      runtime: runTimes.length ? Math.round(runTimes.reduce((a, b) => a + b, 0) / runTimes.length) : null,
      seasons: Number.isInteger(data.number_of_seasons) && data.number_of_seasons > 0 ? data.number_of_seasons : null,
      episodes: Number.isInteger(data.number_of_episodes) && data.number_of_episodes > 0 ? data.number_of_episodes : null,
      directors: (data.created_by || []).map(p => botText(p.name)).filter(Boolean),
      cast, genres, overview: botText(data.overview), poster: botImage(data.poster_path), checkedAt: now,
      providers: normalized, providerError: providers.status === 'rejected'
    };
  }
  const jpDates = (data.release_dates?.results || []).find(r => r.iso_3166_1 === 'JP')?.release_dates || [];
  const theatricalDates = jpDates.filter(r => [2, 3].includes(r.type)).map(r => botDate(r.release_date)).filter(Boolean).sort();
  return {
    source: 'TMDB', id, mediaType: 'movie', title: botText(data.title), originalTitle: botText(data.original_title),
    releaseDate: botDate(data.release_date), japanTheatricalDate: theatricalDates[0] || '',
    runtime: Number.isFinite(data.runtime) && data.runtime > 0 ? data.runtime : null,
    directors: (data.credits?.crew || []).filter(p => p.job === 'Director').map(p => botText(p.name)).filter(Boolean),
    cast, genres, overview: botText(data.overview), poster: botImage(data.poster_path), checkedAt: now,
    providers: normalized, providerError: providers.status === 'rejected'
  };
}
async function botShelf(env) {
  const {results} = await env.DB.prepare('SELECT body, revision FROM films ORDER BY id').all();
  return results.map(r => ({...JSON.parse(r.body), _revision: r.revision}));
}
const botMedia = r => r.movie?.mediaType || 'movie';
const botBrief = r => ({ id: r.id, title: r.title, status: r.status, rating: r.rating, date: r.date, _revision: r._revision });
// Same matching as findFilmRecord() in client/app.js.
function botFindOnShelf(shelf, film) {
  const exact = shelf.find(r => r.movie?.id === film.id && botMedia(r) === film.mediaType);
  if (exact) return { match: 'tmdb', record: exact };
  const year = (film.releaseDate || '').slice(0, 4);
  const compatible = shelf.filter(r => botNormalize(r.title) === botNormalize(film.title)).filter(r => { const known = (r.meta || '').match(/(19\d{2}|20\d{2})年製作/); return !known || !year || known[1] === year; });
  const record = compatible.find(r => r.status === 'watched') || compatible[0];
  return record ? { match: 'title', record } : null;
}
async function botSearch(url, env) {
  const query = (url.searchParams.get('query') || url.searchParams.get('q') || '').trim();
  if (!query || query.length > 200) return botJson({error: 'query を指定してください。'}, 400);
  const key = await botKey(env);
  const [movies, shows] = await Promise.allSettled([
    botTmdb(env, key, 'search/movie', [['query', query], ['region', 'JP'], ['include_adult', 'false']]),
    botTmdb(env, key, 'search/tv', [['query', query], ['include_adult', 'false']])
  ]);
  const list = (res, mediaType) => res.status === 'fulfilled' ? (res.value.results || []).filter(i => Number.isInteger(i.id) && i.id > 0).map(i => ({
    tmdbId: i.id, mediaType, title: botText(i.title || i.name), originalTitle: botText(i.original_title || i.original_name),
    releaseDate: botDate(i.release_date || i.first_air_date), overview: botText(i.overview).slice(0, 160), poster: botImage(i.poster_path),
    popularity: Number.isFinite(i.popularity) ? i.popularity : 0
  })) : [];
  const merged = [...list(movies, 'movie'), ...list(shows, 'tv')];
  if (!merged.length && movies.status === 'rejected') throw movies.reason;
  if (!merged.length && shows.status === 'rejected') throw shows.reason;
  merged.sort((a, b) => b.popularity - a.popularity);
  const shelf = await botShelf(env);
  const limit = Math.min(40, Math.max(1, Number(url.searchParams.get('limit')) || 20));
  return botJson({results: merged.slice(0, limit).map(({popularity, ...film}) => {
    const found = botFindOnShelf(shelf, {id: film.tmdbId, mediaType: film.mediaType, title: film.title, releaseDate: film.releaseDate});
    return {...film, year: film.releaseDate.slice(0, 4), onShelf: found ? {match: found.match, ...botBrief(found.record)} : null};
  })});
}
async function botList(url, env) {
  const q = (url.searchParams.get('q') || '').toLowerCase(), status = url.searchParams.get('status') || '';
  const tmdbId = url.searchParams.get('tmdbId'), mediaType = url.searchParams.get('mediaType') || '';
  if (status && !['watched', 'want'].includes(status)) return botJson({error: 'status は watched か want です。'}, 400);
  if (mediaType && !['movie', 'tv'].includes(mediaType)) return botJson({error: 'mediaType は movie か tv です。'}, 400);
  if (tmdbId != null && !/^[1-9]\d{0,9}$/.test(tmdbId)) return botJson({error: 'tmdbId が不正です。'}, 400);
  const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit')) || 50));
  const matches = (await botShelf(env)).filter(r =>
    (!status || r.status === status) &&
    (tmdbId == null || r.movie?.id === Number(tmdbId)) &&
    (!mediaType || botMedia(r) === mediaType) &&
    (!q || [r.title, r.movie?.title, r.movie?.originalTitle].some(t => typeof t === 'string' && t.toLowerCase().includes(q)))
  ).sort((a, b) => b.updated - a.updated);
  return botJson({total: matches.length, records: matches.slice(0, limit)});
}
async function botCreate(request, env) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!('status' in data)) return botJson({error: 'status を指定してください。'}, 400);
  const fieldError = botFieldError(data);
  if (fieldError) return botJson({error: fieldError}, 400);
  if (data.title != null && (typeof data.title !== 'string' || data.title.length > 1000)) return botJson({error: 'title が不正です。'}, 400);
  let movie = null;
  if (data.tmdbId != null) {
    if (!Number.isInteger(data.tmdbId) || data.tmdbId < 1) return botJson({error: 'tmdbId が不正です。'}, 400);
    const media = data.mediaType == null ? 'movie' : data.mediaType;
    if (!['movie', 'tv'].includes(media)) return botJson({error: 'mediaType は movie か tv です。'}, 400);
    const existing = (await botShelf(env)).find(r => r.movie?.id === data.tmdbId && botMedia(r) === media);
    if (existing) return botJson({error: 'この作品はすでに棚にあります。', record: existing}, 409);
    movie = await botDetails(env, await botKey(env), data.tmdbId, media);
  }
  const title = (typeof data.title === 'string' && data.title.trim()) ? data.title.trim() : (movie?.title || movie?.originalTitle || '');
  if (!title) return botJson({error: 'title か tmdbId を指定してください。'}, 400);
  if (!movie && data.allowDuplicateTitle !== true) {
    const same = (await botShelf(env)).find(r => botNormalize(r.title) === botNormalize(title));
    if (same) return botJson({error: '同じ作品名の記録がすでにあります。別作品として追加する場合は allowDuplicateTitle: true を指定してください。', record: same}, 409);
  }
  const record = {
    id: crypto.randomUUID(), title, status: data.status,
    rating: data.rating ?? 0, date: data.date ?? '', meta: (data.meta ?? '').trim(), review: (data.review ?? '').trim(),
    updated: Date.now(), ...(movie ? {movie} : {})
  };
  for (const k of ['spoiler', 'method', 'service', 'viewings']) if (k in data) record[k] = data[k];
  Object.assign(record, syncLatestViewing(record));
  if (!botClientValid(record)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const body = JSON.stringify(record);
  // Atomic duplicate guard: insert only if no record already has this TMDB id + media type.
  const result = movie
    ? await env.DB.prepare("INSERT INTO films (id, body, revision) SELECT ?, ?, 1 WHERE NOT EXISTS (SELECT 1 FROM films WHERE json_extract(body, '$.movie.id') = ? AND coalesce(json_extract(body, '$.movie.mediaType'), 'movie') = ?)").bind(record.id, body, movie.id, movie.mediaType).run()
    : await env.DB.prepare('INSERT INTO films (id, body, revision) VALUES (?, ?, 1)').bind(record.id, body).run();
  if (result.meta.changes !== 1) {
    const existing = (await botShelf(env)).find(r => r.movie?.id === movie.id && botMedia(r) === movie.mediaType);
    return botJson({error: 'この作品はすでに棚にあります。', record: existing || null}, 409);
  }
  return botJson({record: {...record, _revision: 1}}, 201);
}
async function botUpdate(request, env, id) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!Number.isInteger(data._revision) || data._revision < 1) return botJson({error: '_revision を指定してください。'}, 409);
  const extra = Object.keys(data).filter(k => k !== '_revision' && !BOT_FIELDS.includes(k));
  if (extra.length) return botJson({error: '変更できない項目です: ' + extra.join(', ') + '（変更できるのは ' + BOT_FIELDS.join(', ') + '）'}, 400);
  if (!BOT_FIELDS.some(k => k in data)) return botJson({error: '変更する項目を指定してください。'}, 400);
  const fieldError = botFieldError(data);
  if (fieldError) return botJson({error: fieldError}, 400);
  const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first();
  if (!row) return botJson({error: '記録が見つかりません。'}, 404);
  const current = JSON.parse(row.body);
  if (row.revision !== data._revision) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。', record: {...current, _revision: row.revision}}, 409);
  const next = {...current, updated: Date.now()};
  for (const k of BOT_FIELDS) if (k in data) next[k] = (k === 'review' || k === 'meta' || k === 'service') ? data[k].trim() : data[k];
  if ('viewings' in data) Object.assign(next, syncLatestViewing(next));
  if (!botClientValid(next)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const result = await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(next), id, data._revision).run();
  if (result.meta.changes !== 1) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。'}, 409);
  return botJson({record: {...next, _revision: data._revision + 1}});
}
async function botApi(request, env) {
  const auth = botAuthorized(request, env);
  if (auth === 'unconfigured') return botJson({error: 'ボット用APIは設定されていません。'}, 503);
  if (auth !== 'ok') return Response.json({error: 'ボット用の鍵が必要です。'}, {status: 401, headers: {'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'WWW-Authenticate': 'Bearer'}});
  if (!env.DB) return botJson({error: '保存先の準備が完了していません。'}, 503);
  const url = new URL(request.url), path = url.pathname, method = request.method;
  if (method !== 'GET' && !request.headers.get('Content-Type')?.startsWith('application/json')) return botJson({error: 'Content-Type: application/json で送ってください。'}, 415);
  try {
    if (path === '/api/bot/search') return method === 'GET' ? await botSearch(url, env) : botJson({error: 'この操作は利用できません。'}, 405);
    if (path === '/api/bot/records') {
      if (method === 'GET') return await botList(url, env);
      if (method === 'POST') return await botCreate(request, env);
      return botJson({error: 'この操作は利用できません。'}, 405);
    }
    const extra = await botFeatureRoute(request, env, url, path, method);
    if (extra) return extra;
    const m = /^\/api\/bot\/records\/([^/]+)$/.exec(path);
    if (m) {
      let id;
      try { id = decodeURIComponent(m[1]); } catch { return botJson({error: 'IDが不正です。'}, 400); }
      if (!id || id.length > 200) return botJson({error: 'IDが不正です。'}, 400);
      if (method === 'GET') { const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first(); return row ? botJson({record: {...JSON.parse(row.body), _revision: row.revision}}) : botJson({error: '記録が見つかりません。'}, 404); }
      if (method === 'PATCH') return await botUpdate(request, env, id);
      return botJson({error: 'この操作は利用できません。'}, 405);
    }
    return botJson({error: '見つかりません。'}, 404);
  } catch (e) {
    if (e instanceof BotTmdbError) return botJson({error: e.message}, e.status);
    return botJson({error: '処理できませんでした。時間をおいて再度お試しください。'}, 503);
  }
}

// Viewings, lists and notices for the bot (same rules as the UI).
async function botAddViewing(request, env, id) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!Number.isInteger(data._revision) || data._revision < 1) return botJson({error: '_revision を指定してください。'}, 409);
  const viewing = { id: crypto.randomUUID(), date: data.date ?? '', method: data.method ?? '', service: typeof data.service === 'string' ? data.service.trim() : (data.service ?? ''), rating: data.rating ?? 0, note: typeof data.note === 'string' ? data.note.trim() : (data.note ?? '') };
  const e = viewingError(viewing);
  if (e) return botJson({error: e}, 400);
  const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first();
  if (!row) return botJson({error: '記録が見つかりません。'}, 404);
  const current = JSON.parse(row.body);
  if (row.revision !== data._revision) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。', record: {...current, _revision: row.revision}}, 409);
  const next = {...addViewing(current, viewing), updated: Date.now()};
  if (!botClientValid(next)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const result = await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(next), id, data._revision).run();
  if (result.meta.changes !== 1) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。'}, 409);
  return botJson({record: {...next, _revision: data._revision + 1}, viewCount: viewCount(next)}, 201);
}
async function botListWithItems(env, list) {
  const ids = list.items.map(i => i.recordId);
  const rows = ids.length ? (await env.DB.prepare('SELECT id, body, revision FROM films WHERE id IN (SELECT value FROM json_each(?))').bind(JSON.stringify(ids)).all()).results : [];
  const byId = new Map(rows.map(r => [r.id, {...JSON.parse(r.body), _revision: r.revision}]));
  return {...list, items: list.items.map((it, i) => { const r = byId.get(it.recordId); return {...it, rank: i + 1, record: r ? {...botBrief(r), tmdbId: r.movie?.id ?? null, mediaType: r.movie ? botMedia(r) : null} : null}; })};
}
async function botFeatureRoute(request, env, url, path, method) {
  const no = () => botJson({error: 'この操作は利用できません。'}, 405);
  const send = ([status, data]) => botJson(data, status);
  const body = () => request.json().catch(() => null);
  let m = /^\/api\/bot\/records\/([^/]+)\/viewings$/.exec(path);
  if (m) {
    let id; try { id = decodeURIComponent(m[1]); } catch { return botJson({error: 'IDが不正です。'}, 400); }
    return method === 'POST' ? botAddViewing(request, env, id) : no();
  }
  if (path === '/api/bot/lists') {
    if (method === 'GET') return botJson({lists: (await listsList(env)).map(l => ({...l, itemCount: l.items.length}))});
    if (method === 'POST') { const [status, data] = await listCreate(env, await body(), {requireExisting: true}); return botJson(data.list ? {list: await botListWithItems(env, data.list)} : data, status); }
    return no();
  }
  m = /^\/api\/bot\/lists\/([^/]+)$/.exec(path);
  if (m) {
    let id; try { id = decodeURIComponent(m[1]); } catch { return botJson({error: 'IDが不正です。'}, 400); }
    if (method === 'GET') { const l = await listGet(env, id); return l ? botJson({list: await botListWithItems(env, l)}) : botJson({error: 'リストが見つかりません。'}, 404); }
    if (method === 'PATCH') {
      const input = await body();
      const extra = input && typeof input === 'object' ? Object.keys(input).filter(k => !['_revision', 'name', 'description', 'items'].includes(k)) : [];
      if (extra.length) return botJson({error: '変更できない項目です: ' + extra.join(', ') + '（変更できるのは name, description, items）'}, 400);
      const [status, data] = await listUpdate(env, id, input, {requireExisting: true});
      return botJson(data.list && status === 200 ? {list: await botListWithItems(env, data.list)} : data, status);
    }
    return no();
  }
  if (path === '/api/bot/notices') return method === 'GET' ? botJson(await noticesList(env, {unreadOnly: url.searchParams.get('unread') === '1', limit: url.searchParams.get('limit') || 50, since: url.searchParams.get('since') || 0, origin: url.origin})) : no();
  m = /^\/api\/bot\/records\/([^/]+)\/link$/.exec(path);
  if (m) {
    let id; try { id = decodeURIComponent(m[1]); } catch { return botJson({error: 'IDが不正です。'}, 400); }
    return method === 'POST' ? botLink(request, env, id) : no();
  }
  if (path === '/api/bot/notices/read') return method === 'POST' ? send(await noticesMarkRead(env, await body())) : no();
  return null;
}

// Link an existing record (e.g. 「確認が必要」) to a TMDB work. Only movie + enrichment change;
// title, rating, review, dates etc. are kept. The pre-link body is kept in enrichment_snapshots.
async function botLink(request, env, id) {
  const data = await request.json().catch(() => null);
  if (!data || typeof data !== 'object' || Array.isArray(data)) return botJson({error: 'JSON の本文が必要です。'}, 400);
  if (!Number.isInteger(data._revision) || data._revision < 1) return botJson({error: '_revision を指定してください。'}, 409);
  if (!Number.isInteger(data.tmdbId) || data.tmdbId < 1) return botJson({error: 'tmdbId が不正です。'}, 400);
  const media = data.mediaType == null ? 'movie' : data.mediaType;
  if (!['movie', 'tv'].includes(media)) return botJson({error: 'mediaType は movie か tv です。'}, 400);
  const row = await env.DB.prepare('SELECT body, revision FROM films WHERE id = ?').bind(id).first();
  if (!row) return botJson({error: '記録が見つかりません。'}, 404);
  const current = JSON.parse(row.body);
  if (row.revision !== data._revision) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。', record: {...current, _revision: row.revision}}, 409);
  const other = (await botShelf(env)).find(r => r.id !== id && r.movie?.id === data.tmdbId && botMedia(r) === media);
  if (other) return botJson({error: 'この作品は別の記録に紐づいています。', record: other}, 409);
  const movie = await botDetails(env, await botKey(env), data.tmdbId, media);
  const reason = typeof data.reason === 'string' && data.reason.trim() ? data.reason.trim().slice(0, 200) : 'ボットで確認して紐づけ';
  const next = {...current, movie, enrichment: {status: 'linked', reason, checkedAt: Date.now(), candidates: [], ...(current.enrichment ? {previous: {status: current.enrichment.status, reason: current.enrichment.reason}} : {})}};
  if (!botClientValid(next)) return botJson({error: '記録の形式が正しくありません。'}, 400);
  const saved = await env.DB.batch([
    env.DB.prepare('INSERT OR IGNORE INTO enrichment_snapshots (id, body, revision) VALUES (?, ?, ?)').bind(id, row.body, row.revision),
    env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(next), id, data._revision)
  ]);
  if (saved[1].meta.changes !== 1) return botJson({error: '別の端末で更新されています。最新の記録を取得し直してください。'}, 409);
  return botJson({record: {...next, _revision: data._revision + 1}});
}

// Filmarks-style features: viewing method / spoiler / re-watches (stored inside
// each record body as optional keys), user lists, and want-list notices.
// Everything here is additive: existing records are never rewritten by the
// notice checker — it only writes to the new lists / notices / watch_checks tables.
const VIEW_METHODS = ['theater', 'streaming', 'tv', 'disc', 'other'];
// Dates may be partial: YYYY, YYYY-MM or YYYY-MM-DD (or empty).
const PARTIAL_DATE = /^\d{4}(-(0[1-9]|1[0-2])(-(0[1-9]|[12]\d|3[01]))?)?$/;
const ftDateOk = v => v === '' || PARTIAL_DATE.test(v);
const ftRatingOk = v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 5 && Math.abs(v * 10 - Math.round(v * 10)) < 0.000001;
function viewingError(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return '鑑賞記録の形式が正しくありません。';
  if (typeof v.id !== 'string' || !v.id || v.id.length > 80) return '鑑賞記録のIDが不正です。';
  if (typeof v.date !== 'string' || !ftDateOk(v.date)) return '鑑賞日は "YYYY-MM-DD"・"YYYY-MM"・"YYYY" か空文字で指定してください。';
  if (typeof v.method !== 'string' || (v.method !== '' && !VIEW_METHODS.includes(v.method))) return '鑑賞方法は ' + VIEW_METHODS.join(' / ') + ' か空文字です。';
  if (typeof v.service !== 'string' || v.service.length > 100) return '配信サービス名は100文字以内の文字列です。';
  if (!ftRatingOk(v.rating)) return '鑑賞ごとの評価は 0〜5（小数第1位まで）です。';
  if (typeof v.note !== 'string' || v.note.length > 5000) return '鑑賞メモは5000文字以内の文字列です。';
  return '';
}
// Optional record keys. Absent keys are always valid, so existing records are unaffected.
function extrasError(r) {
  if ('spoiler' in r && typeof r.spoiler !== 'boolean') return 'spoiler は true / false です。';
  if ('method' in r && (typeof r.method !== 'string' || (r.method !== '' && !VIEW_METHODS.includes(r.method)))) return 'method は ' + VIEW_METHODS.join(' / ') + ' か空文字です。';
  if ('service' in r && (typeof r.service !== 'string' || r.service.length > 100)) return 'service は100文字以内の文字列です。';
  if ('viewings' in r) {
    if (!Array.isArray(r.viewings) || r.viewings.length > 500) return 'viewings は配列（500件まで）です。';
    for (const v of r.viewings) { const e = viewingError(v); if (e) return e; }
    if (new Set(r.viewings.map(v => v.id)).size !== r.viewings.length) return '鑑賞記録のIDが重複しています。';
  }
  return '';
}
const extrasValid = r => !extrasError(r);
// Viewings sorted oldest → newest (undated first). The record's date/method/service
// mirror the newest viewing so existing sorting and display keep working.
function syncLatestViewing(r) {
  if (!Array.isArray(r.viewings) || !r.viewings.length) return r;
  const viewings = r.viewings.map((v, i) => [v, i]).sort((a, b) => (a[0].date || '').localeCompare(b[0].date || '') || a[1] - b[1]).map(x => x[0]);
  const latest = viewings.at(-1);
  return { ...r, viewings, date: latest.date || r.date, method: latest.method, service: latest.service };
}
function addViewing(r, v) {
  const seed = Array.isArray(r.viewings) ? r.viewings : (r.status === 'watched' ? [{ id: 'v0', date: r.date || '', method: r.method || '', service: r.service || '', rating: r.rating || 0, note: '' }] : []);
  const next = syncLatestViewing({ ...r, status: 'watched', viewings: [...seed, v] });
  if (v.rating > 0) next.rating = v.rating;
  return next;
}
const viewCount = r => Array.isArray(r.viewings) && r.viewings.length ? r.viewings.length : (r.status === 'watched' ? 1 : 0);

// ---- Lists ----
function listError(l) {
  if (!l || typeof l !== 'object') return 'リストの形式が正しくありません。';
  if (typeof l.name !== 'string' || !l.name.trim() || l.name.length > 100) return 'リスト名（100文字以内）を入力してください。';
  if (typeof l.description !== 'string' || l.description.length > 2000) return '説明は2000文字以内です。';
  if (!Array.isArray(l.items) || l.items.length > 500) return '作品は500件までです。';
  for (const it of l.items) if (!it || typeof it.recordId !== 'string' || !it.recordId || it.recordId.length > 200 || typeof it.title !== 'string' || it.title.length > 1000 || typeof it.note !== 'string' || it.note.length > 1000) return 'リストの作品の形式が正しくありません。';
  if (new Set(l.items.map(i => i.recordId)).size !== l.items.length) return '同じ作品が重複しています。';
  return '';
}
function ftList(input, previous) {
  const now = Date.now();
  return {
    id: previous?.id || crypto.randomUUID(), name: typeof input.name === 'string' ? input.name.trim() : previous?.name,
    description: typeof input.description === 'string' ? input.description.trim() : (previous?.description ?? ''),
    items: Array.isArray(input.items) ? input.items.map(i => typeof i === 'string' ? { recordId: i, title: '', note: '' } : { recordId: i?.recordId, title: typeof i?.title === 'string' ? i.title : '', note: typeof i?.note === 'string' ? i.note : '' }) : (previous?.items ?? []),
    created: previous?.created || now, updated: now
  };
}
// Fill item titles from the shelf (titles are a snapshot so a list survives a deleted record).
async function ftFillTitles(env, list, requireExisting) {
  if (!list.items.length) return '';
  const ids = list.items.map(i => i.recordId);
  const rows = (await env.DB.prepare("SELECT id, json_extract(body,'$.title') AS title FROM films WHERE id IN (SELECT value FROM json_each(?))").bind(JSON.stringify(ids)).all()).results;
  const titles = new Map(rows.map(r => [r.id, r.title]));
  for (const it of list.items) {
    if (titles.has(it.recordId)) it.title = titles.get(it.recordId);
    else if (requireExisting) return '棚にない記録IDです: ' + it.recordId;
  }
  return '';
}
async function listsList(env) {
  const { results } = await env.DB.prepare('SELECT body, revision FROM lists').all();
  return results.map(r => ({ ...JSON.parse(r.body), _revision: r.revision })).sort((a, b) => b.updated - a.updated);
}
async function listGet(env, id) {
  const row = await env.DB.prepare('SELECT body, revision FROM lists WHERE id = ?').bind(id).first();
  return row ? { ...JSON.parse(row.body), _revision: row.revision } : null;
}
// Shared by the UI (cookie) and the bot API. Returns [status, data].
async function listCreate(env, input, { requireExisting = false } = {}) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return [400, { error: 'JSON の本文が必要です。' }];
  const list = ftList({ description: '', ...input });
  const e = listError(list) || await ftFillTitles(env, list, requireExisting);
  if (e) return [400, { error: e }];
  const count = await env.DB.prepare('SELECT count(*) AS c FROM lists').first();
  if (count.c >= 200) return [400, { error: 'リストは200個までです。' }];
  await env.DB.prepare('INSERT INTO lists (id, body, revision) VALUES (?, ?, 1)').bind(list.id, JSON.stringify(list)).run();
  return [201, { list: { ...list, _revision: 1 } }];
}
async function listUpdate(env, id, input, { requireExisting = false } = {}) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return [400, { error: 'JSON の本文が必要です。' }];
  if (!Number.isInteger(input._revision) || input._revision < 1) return [409, { error: '_revision を指定してください。' }];
  const current = await listGet(env, id);
  if (!current) return [404, { error: 'リストが見つかりません。' }];
  if (current._revision !== input._revision) return [409, { error: '別の端末で更新されています。最新のリストを取得し直してください。', list: current }];
  const { _revision, ...prev } = current;
  const list = ftList(input, prev);
  const e = listError(list) || await ftFillTitles(env, list, requireExisting);
  if (e) return [400, { error: e }];
  const r = await env.DB.prepare('UPDATE lists SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(list), id, input._revision).run();
  if (r.meta.changes !== 1) return [409, { error: '別の端末で更新されています。最新のリストを取得し直してください。' }];
  return [200, { list: { ...list, _revision: input._revision + 1 } }];
}

// ---- Notices (want list: JP streaming availability + JP release dates) ----
const NOTICE_BATCH = 10;
const ftTokyoDate = (offsetDays = 0) => new Date(Date.now() + 9 * 3600000 + offsetDays * 86400000).toISOString().slice(0, 10);
const ftNames = (p, keys) => new Set(keys.flatMap(k => Array.isArray(p?.[k]) ? p[k] : []));
const STREAM_KINDS = [['flatrate', '見放題'], ['free', '無料'], ['ads', '広告付き無料']];
function ftParse(s) { try { return s ? JSON.parse(s) : null; } catch { return null; } }
// Pure: compares the previous provider snapshot with the fresh TMDB data and returns new notices.
function noticesFor(row, prevProviders, fresh, now = Date.now()) {
  const out = [], base = { recordId: row.id, title: row.title, tmdbId: row.tid, mediaType: row.media, poster: typeof row.poster === 'string' ? row.poster : '' };
  const providers = fresh.providers;
  if (prevProviders && providers) {
    const before = ftNames(prevProviders, ['flatrate', 'free', 'ads']);
    for (const [k, label] of STREAM_KINDS) for (const name of providers[k] || []) {
      if (before.has(name)) continue;
      before.add(name);
      out.push({ id: `stream:${row.id}:${name}`, kind: 'stream', ...base, provider: name, monetization: k, message: `「${row.title}」が${name}で${label}配信されています。` });
    }
    const anyBefore = ftNames(prevProviders, ['flatrate', 'free', 'ads', 'rent', 'buy']).size;
    const paid = [...ftNames(providers, ['rent', 'buy'])];
    if (!anyBefore && paid.length && !ftNames(providers, ['flatrate', 'free', 'ads']).size) out.push({ id: `digital:${row.id}`, kind: 'digital', ...base, provider: paid[0], message: `「${row.title}」がレンタル・購入で配信開始されました（${paid.slice(0, 3).join('、')}）。` });
  }
  const date = fresh.releaseDate;
  if (date) {
    const today = ftTokyoDate(0), label = row.media === 'tv' ? '放送開始' : '日本公開';
    if (date > today && date <= ftTokyoDate(14)) out.push({ id: `release-soon:${row.id}:${date}`, kind: 'release-soon', ...base, date, message: `「${row.title}」の${label}日が近づいています（${date.replaceAll('-', '/')}）。` });
    else if (date <= today && date >= ftTokyoDate(-7)) out.push({ id: `release:${row.id}:${date}`, kind: 'release', ...base, date, message: `「${row.title}」が${label}日を迎えました（${date.replaceAll('-', '/')}）。` });
  }
  return out.map(n => ({ ...n, created: now }));
}
function ftFresh(data, media) {
  const jp = data['watch/providers']?.results?.JP;
  const providers = {};
  for (const k of ['flatrate', 'rent', 'buy', 'free', 'ads']) providers[k] = [...new Set((jp?.[k] || []).map(p => typeof p.provider_name === 'string' ? p.provider_name : '').filter(Boolean))];
  let releaseDate = '';
  if (media === 'tv') releaseDate = /^\d{4}-\d{2}-\d{2}/.test(data.first_air_date || '') ? data.first_air_date.slice(0, 10) : '';
  else {
    const dates = ((data.release_dates?.results || []).find(r => r.iso_3166_1 === 'JP')?.release_dates || []).filter(r => [2, 3].includes(r.type)).map(r => String(r.release_date || '').slice(0, 10)).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d)).sort();
    // Prefer the next upcoming JP theatrical date (re-releases), else the first one.
    const today = ftTokyoDate(-7);
    releaseDate = dates.find(d => d >= today) || dates[0] || '';
  }
  return { providers: data['watch/providers'] ? providers : null, releaseDate };
}
async function runNoticeCheck(env, limit = NOTICE_BATCH) {
  if (!env.DB || !env.TMDB_CONFIG_KEY) return { checked: 0, created: 0, skipped: 'unconfigured' };
  const key = await storedKey(env);
  if (!key) return { checked: 0, created: 0, skipped: 'unconfigured' };
  const { results } = await env.DB.prepare("SELECT f.id, json_extract(f.body,'$.title') AS title, json_extract(f.body,'$.movie.id') AS tid, coalesce(json_extract(f.body,'$.movie.mediaType'),'movie') AS media, json_extract(f.body,'$.movie.poster') AS poster, json_extract(f.body,'$.movie.providers') AS prov, c.body AS cbody FROM films f LEFT JOIN watch_checks c ON c.record_id = f.id WHERE json_extract(f.body,'$.status') = 'want' AND json_extract(f.body,'$.movie.id') IS NOT NULL ORDER BY coalesce(c.checked_at, 0), f.id LIMIT ?").bind(limit).all();
  const now = Date.now(), statements = [], noticeIdx = [];
  const outcomes = await Promise.all(results.map(async row => {
    if (!Number.isInteger(row.tid) || !['movie', 'tv'].includes(row.media)) return null;
    try {
      const res = await upstream(row.media + '/' + row.tid, key, [['append_to_response', row.media === 'tv' ? 'watch/providers' : 'release_dates,watch/providers']]);
      if (res.status === 429) return null; // try again next run
      if (!res.ok) return { row, fresh: null, status: res.status };
      return { row, fresh: ftFresh(await res.json(), row.media) };
    } catch { return null; }
  }));
  for (const o of outcomes) {
    if (!o) continue;
    const prevCheck = ftParse(o.row.cbody);
    const prev = prevCheck ? prevCheck.providers : ftParse(o.row.prov);
    const snapshot = o.fresh ? { providers: o.fresh.providers || prev || null, releaseDate: o.fresh.releaseDate } : { providers: prev || null, releaseDate: prevCheck?.releaseDate || '', error: o.status };
    if (o.fresh) for (const n of noticesFor(o.row, prev, o.fresh, now)) { noticeIdx.push(statements.length); statements.push(env.DB.prepare('INSERT OR IGNORE INTO notices (id, body, created, read) VALUES (?, ?, ?, 0)').bind(n.id, JSON.stringify(n), now)); }
    statements.push(env.DB.prepare('INSERT INTO watch_checks (record_id, body, checked_at) VALUES (?, ?, ?) ON CONFLICT(record_id) DO UPDATE SET body = excluded.body, checked_at = excluded.checked_at').bind(o.row.id, JSON.stringify(snapshot), now));
  }
  let created = 0;
  if (statements.length) { const r = await env.DB.batch(statements); created = noticeIdx.reduce((n, i) => n + (r[i]?.meta?.changes || 0), 0); }
  return { checked: outcomes.filter(Boolean).length, created };
}
const NOTICE_LABELS = { stream: '配信開始', digital: 'レンタル・購入開始', 'release-soon': 'もうすぐ公開', release: '公開日' };
async function noticesList(env, { unreadOnly = false, limit = 100, since = 0, origin = '' } = {}) {
  const lim = Math.min(200, Math.max(1, Number(limit) || 100)), after = Number.isFinite(Number(since)) ? Number(since) : 0;
  const { results } = await env.DB.prepare(`SELECT id, body, created, read FROM notices WHERE created > ? ${unreadOnly ? 'AND read = 0 ' : ''}ORDER BY created DESC, id LIMIT ?`).bind(after, lim).all();
  const unread = (await env.DB.prepare('SELECT count(*) AS c FROM notices WHERE read = 0').first()).c;
  const progress = await env.DB.prepare("SELECT (SELECT count(*) FROM films WHERE json_extract(body,'$.status') = 'want' AND json_extract(body,'$.movie.id') IS NOT NULL) AS watching, (SELECT count(*) FROM watch_checks w JOIN films f ON f.id = w.record_id WHERE json_extract(f.body,'$.status') = 'want') AS checked, (SELECT max(checked_at) FROM watch_checks) AS lastChecked").first();
  const now = Date.now();
  return { now, unread, progress, notices: results.map(r => { const n = JSON.parse(r.body), media = n.mediaType === 'tv' ? 'tv' : 'movie'; return { ...n, id: r.id, created: r.created, read: !!r.read, kindLabel: NOTICE_LABELS[n.kind] || 'お知らせ', tmdbUrl: Number.isInteger(n.tmdbId) ? `https://www.themoviedb.org/${media}/${n.tmdbId}` : '', watchUrl: Number.isInteger(n.tmdbId) ? `https://www.themoviedb.org/${media}/${n.tmdbId}/watch?locale=JP` : '', appUrl: origin ? origin + '/' : '' }; }) };
}
async function noticesMarkRead(env, input) {
  if (input?.all === true) { const r = await env.DB.prepare('UPDATE notices SET read = 1 WHERE read = 0').run(); return [200, { marked: r.meta.changes }]; }
  if (!Array.isArray(input?.ids) || !input.ids.length || input.ids.length > 500 || input.ids.some(i => typeof i !== 'string' || i.length > 400)) return [400, { error: 'ids（配列）か all: true を指定してください。' }];
  const r = await env.DB.prepare('UPDATE notices SET read = 1 WHERE read = 0 AND id IN (SELECT value FROM json_each(?))').bind(JSON.stringify(input.ids)).run();
  return [200, { marked: r.meta.changes }];
}

// ---- Cookie (UI) routes: /api/lists*, /api/notices* ----
async function featureApi(request, env, url) {
  const path = url.pathname, method = request.method;
  const body = async () => request.json().catch(() => null);
  const send = ([status, data]) => json(data, status);
  if (path === '/api/lists') {
    if (method === 'GET') return json({ lists: await listsList(env) });
    if (method === 'POST') return send(await listCreate(env, await body()));
    return json({ error: 'この操作は利用できません。' }, 405);
  }
  const m = /^\/api\/lists\/([^/]+)$/.exec(path);
  if (m) {
    let id; try { id = decodeURIComponent(m[1]); } catch { return json({ error: 'IDが不正です。' }, 400); }
    if (method === 'GET') { const l = await listGet(env, id); return l ? json({ list: l }) : json({ error: 'リストが見つかりません。' }, 404); }
    if (method === 'PUT') return send(await listUpdate(env, id, await body()));
    if (method === 'DELETE') {
      const data = await body();
      if (!Number.isInteger(data?._revision)) return json({ error: '_revision を指定してください。' }, 409);
      const ok = await softDelete(env, 'list', id, data._revision);
      return ok ? json({ saved: true }) : json({ error: '別の端末で更新されています。開き直してください。' }, 409);
    }
    return json({ error: 'この操作は利用できません。' }, 405);
  }
  if (path === '/api/notices' && method === 'GET') return json(await noticesList(env, { unreadOnly: url.searchParams.get('unread') === '1', limit: url.searchParams.get('limit'), since: url.searchParams.get('since') || 0, origin: url.origin }));
  if (path === '/api/notices/read' && method === 'POST') return send(await noticesMarkRead(env, await body()));
  if (path === '/api/notices/check' && method === 'POST') {
    const last = (await env.DB.prepare('SELECT max(checked_at) AS t FROM watch_checks').first())?.t || 0;
    if (Date.now() - last < 20000) return json({ error: '少し時間をおいてからもう一度お試しください。' }, 429);
    return json(await runNoticeCheck(env));
  }
  return json({ error: '見つかりません。' }, 404);
}

// ゴミ箱 (soft delete, 30 days) and automatic in-D1 backups (weekly, keep 8).
// Deleting a record or list moves the row into `trash` in the same transaction.
const TRASH_DAYS = 30, BACKUP_KEEP = 8, BACKUP_CHUNK = 250000, BACKUP_EVERY = 7 * 86400000;
async function softDelete(env, kind, id, revision) {
  const table = kind === 'list' ? 'lists' : 'films', now = Date.now();
  const r = await env.DB.batch([
    env.DB.prepare(`INSERT INTO trash (id, kind, item_id, body, revision, deleted_at) SELECT ?, ?, id, body, revision, ? FROM ${table} WHERE id = ? AND revision = ?`).bind(kind + ':' + id + ':' + now, kind, now, id, revision),
    env.DB.prepare(`DELETE FROM ${table} WHERE id = ? AND revision = ?`).bind(id, revision)
  ]);
  return r[1].meta.changes === 1;
}
async function trashList(env) {
  const { results } = await env.DB.prepare("SELECT id, kind, item_id, deleted_at, coalesce(json_extract(body,'$.title'), json_extract(body,'$.name')) AS title, json_extract(body,'$.status') AS status, json_extract(body,'$.rating') AS rating, json_extract(body,'$.movie.poster') AS poster FROM trash ORDER BY deleted_at DESC").all();
  return results.map(r => ({ id: r.id, kind: r.kind, itemId: r.item_id, title: r.title || '', status: r.status || null, rating: r.rating ?? null, poster: typeof r.poster === 'string' ? r.poster : '', deletedAt: r.deleted_at, purgeAt: r.deleted_at + TRASH_DAYS * 86400000 }));
}
async function trashRestore(env, trashId) {
  const row = await env.DB.prepare('SELECT * FROM trash WHERE id = ?').bind(trashId).first();
  if (!row) return [404, { error: 'ゴミ箱に見つかりません。' }];
  const table = row.kind === 'list' ? 'lists' : 'films';
  if (await env.DB.prepare(`SELECT 1 FROM ${table} WHERE id = ?`).bind(row.item_id).first()) return [409, { error: '同じIDのデータがすでにあります。' }];
  if (row.kind === 'record') {
    const body = JSON.parse(row.body);
    if (body.movie?.id) {
      const dup = await env.DB.prepare("SELECT json_extract(body,'$.title') AS title FROM films WHERE json_extract(body,'$.movie.id') = ? AND coalesce(json_extract(body,'$.movie.mediaType'),'movie') = ?").bind(body.movie.id, body.movie.mediaType || 'movie').first();
      if (dup) return [409, { error: `同じ作品（${dup.title}）がすでに棚にあります。先にそちらを削除するか、そのままにしてください。` }];
    }
  }
  const r = await env.DB.batch([
    env.DB.prepare(`INSERT INTO ${table} (id, body, revision) SELECT item_id, body, revision + 1 FROM trash WHERE id = ? AND NOT EXISTS (SELECT 1 FROM ${table} WHERE id = trash.item_id)`).bind(trashId),
    env.DB.prepare(`DELETE FROM trash WHERE id = ? AND EXISTS (SELECT 1 FROM ${table} WHERE id = trash.item_id)`).bind(trashId)
  ]);
  return r[0].meta.changes === 1 ? [200, { restored: true, kind: row.kind, id: row.item_id }] : [409, { error: '元に戻せませんでした。開き直してください。' }];
}
async function trashPurge(env, olderThan = Date.now() - TRASH_DAYS * 86400000) {
  return (await env.DB.prepare('DELETE FROM trash WHERE deleted_at < ?').bind(olderThan).run()).meta.changes;
}
// Full backup as one JSON document. Raw bodies are spliced in without parsing to keep CPU low.
// The file is also a valid "yoin-v1" backup, so the existing 「バックアップを読み込む」 can restore records.
async function createBackup(env, kind = 'auto') {
  const now = Date.now();
  const tables = {};
  for (const [name, sql] of [['films', 'SELECT id, body, revision FROM films ORDER BY id'], ['lists', 'SELECT id, body, revision FROM lists ORDER BY id'], ['notices', 'SELECT id, body, created, read FROM notices ORDER BY id'], ['watch_checks', 'SELECT record_id, body, checked_at FROM watch_checks ORDER BY record_id'], ['trash', 'SELECT id, kind, item_id, body, revision, deleted_at FROM trash ORDER BY id'], ['enrichment_snapshots', 'SELECT id, body, revision FROM enrichment_snapshots ORDER BY id']]) tables[name] = (await env.DB.prepare(sql).all()).results;
  const row = r => '{' + Object.entries(r).map(([k, v]) => JSON.stringify(k) + ':' + (k === 'body' ? v : JSON.stringify(v))).join(',') + '}';
  const summary = Object.fromEntries(Object.entries(tables).map(([k, v]) => [k, v.length]));
  const text = '{"format":"yoin-v1","kind":"full-backup","version":1,"created":' + now + ',"summary":' + JSON.stringify(summary) + ',"records":[' + tables.films.map(r => r.body).join(',') + '],"tables":{' + Object.entries(tables).map(([k, v]) => JSON.stringify(k) + ':[' + v.map(row).join(',') + ']').join(',') + '}}';
  const id = 'backup-' + new Date(now + 9 * 3600000).toISOString().slice(0, 19).replace(/[-:T]/g, '') + '-' + kind + '-' + crypto.randomUUID().slice(0, 8);
  const chunks = [];
  for (let i = 0; i < text.length; i += BACKUP_CHUNK) chunks.push(text.slice(i, i + BACKUP_CHUNK));
  await env.DB.batch([
    ...chunks.map((c, i) => env.DB.prepare('INSERT INTO backup_chunks (backup_id, idx, data) VALUES (?, ?, ?)').bind(id, i, c)),
    env.DB.prepare('INSERT INTO backups (id, created, kind, size, chunks, summary) VALUES (?, ?, ?, ?, ?, ?)').bind(id, now, kind, text.length, chunks.length, JSON.stringify(summary))
  ]);
  // Keep the newest BACKUP_KEEP backups.
  const old = (await env.DB.prepare('SELECT id FROM backups ORDER BY created DESC LIMIT -1 OFFSET ?').bind(BACKUP_KEEP).all()).results;
  if (old.length) await env.DB.batch(old.flatMap(o => [env.DB.prepare('DELETE FROM backup_chunks WHERE backup_id = ?').bind(o.id), env.DB.prepare('DELETE FROM backups WHERE id = ?').bind(o.id)]));
  return { id, created: now, size: text.length, chunks: chunks.length, summary };
}
async function backupsList(env) {
  return (await env.DB.prepare('SELECT id, created, kind, size, chunks, summary FROM backups ORDER BY created DESC').all()).results.map(b => ({ ...b, summary: JSON.parse(b.summary) }));
}
async function backupDownload(env, id) {
  const meta = await env.DB.prepare('SELECT id, created, chunks FROM backups WHERE id = ?').bind(id).first();
  if (!meta) return json({ error: 'バックアップが見つかりません。' }, 404);
  const { results } = await env.DB.prepare('SELECT idx, data FROM backup_chunks WHERE backup_id = ? ORDER BY idx').bind(id).all();
  if (results.length !== meta.chunks) return json({ error: 'バックアップが壊れています。' }, 500);
  const date = new Date(meta.created + 9 * 3600000).toISOString().slice(0, 10);
  return new Response(results.map(r => r.data).join(''), { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Content-Disposition': `attachment; filename="yoin-full-backup-${date}.json"`, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' } });
}
// Cron: purge old trash, then a weekly backup when the newest one is older than 7 days.
async function runMaintenance(env) {
  if (!env.DB) return null;
  const purged = await trashPurge(env);
  const last = (await env.DB.prepare('SELECT max(created) AS t FROM backups').first())?.t || 0;
  const backup = Date.now() - last >= BACKUP_EVERY ? await createBackup(env, 'auto') : null;
  return { purged, backup };
}
const UI_BACKGROUNDS = ['simple', 'curtain', 'screen'];
async function safetyApi(request, env, url) {
  const path = url.pathname, method = request.method;
  const body = () => request.json().catch(() => null);
  const send = ([status, data]) => json(data, status);
  if (path === '/api/trash' && method === 'GET') return json({ items: await trashList(env), days: TRASH_DAYS });
  if (path === '/api/trash/restore' && method === 'POST') { const d = await body(); return typeof d?.id === 'string' ? send(await trashRestore(env, d.id)) : json({ error: 'id を指定してください。' }, 400); }
  if (path === '/api/trash/purge' && method === 'POST') {
    const d = await body();
    if (typeof d?.id !== 'string') return json({ error: 'id を指定してください。' }, 400);
    const r = await env.DB.prepare('DELETE FROM trash WHERE id = ?').bind(d.id).run();
    return json({ purged: r.meta.changes });
  }
  if (path === '/api/backups' && method === 'GET') return json({ backups: await backupsList(env), keep: BACKUP_KEEP });
  if (path === '/api/backups' && method === 'POST') {
    const last = (await env.DB.prepare("SELECT max(created) AS t FROM backups WHERE kind = 'manual'").first())?.t || 0;
    if (Date.now() - last < 600000) return json({ error: '手動バックアップは10分に1回までです。' }, 429);
    return json({ backup: await createBackup(env, 'manual') }, 201);
  }
  const m = /^\/api\/backups\/([^/]+)\/download$/.exec(path);
  if (m && method === 'GET') return backupDownload(env, decodeURIComponent(m[1]));
  if (path === '/api/settings/ui') {
    // 表示の好みだけを保存する（app_settings の 'ui' 行のみ。他の行は読み書きしない）。
    if (method === 'GET') { const row = await env.DB.prepare("SELECT body FROM app_settings WHERE name = 'ui'").first(); let data = {}; try { data = row ? JSON.parse(row.body) : {}; } catch {} return json({ background: UI_BACKGROUNDS.includes(data.background) ? data.background : null }); }
    if (method === 'PUT') {
      const d = await body();
      if (!UI_BACKGROUNDS.includes(d?.background)) return json({ error: `background は ${UI_BACKGROUNDS.join(' / ')} のいずれかです。` }, 400);
      await env.DB.prepare("INSERT INTO app_settings(name, body) VALUES('ui', ?) ON CONFLICT(name) DO UPDATE SET body = excluded.body").bind(JSON.stringify({ background: d.background, updated: Date.now() })).run();
      return json({ background: d.background });
    }
    return json({ error: 'この操作は利用できません。' }, 405);
  }
  return json({ error: '見つかりません。' }, 404);
}

const json = (data, status = 200) => Response.json(data, {status, headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function validate(r) {
  return r && typeof r.id==='string' && r.id.length>0 && r.id.length<=200 && typeof r.title==='string' && r.title.trim() && r.title.length<=1000 && ['watched','want'].includes(r.status) && Number.isFinite(r.rating) && r.rating>=0 && r.rating<=5 && Number.isFinite(r.updated) && ['date','meta','review'].every(k=>typeof r[k]==='string' && r[k].length<=100000) && extrasValid(r);
}
function clean(r) { const {_revision,...body}=r; return body; }
async function api(request, env) {
  if(new URL(request.url).pathname.startsWith('/api/bot/'))return botApi(request,env);
  if(!request.headers.get('oai-authenticated-user-id'))return json({error:'同じChatGPTアカウントでログインしてください。'},401);
  if(new URL(request.url).pathname.startsWith('/api/tmdb'))return tmdb(request,env);
  if(!env.DB)return json({error:'保存先の準備が完了していません。'},503);
  const url=new URL(request.url);
  if(request.method!=='GET' && (request.headers.get('Origin')!==url.origin || !request.headers.get('Content-Type')?.startsWith('application/json')))return json({error:'この画面から操作してください。'},403);
  try {
    if(url.pathname==='/api/enrich')return await enrichBatch(request,env);
    if(/^\/api\/(lists|notices)(\/|$)/.test(url.pathname))return await featureApi(request,env,url);
    if(/^\/api\/(trash|backups|settings)(\/|$)/.test(url.pathname))return await safetyApi(request,env,url);
    if(url.pathname==='/api/records' && request.method==='GET') {
      const {results}=await env.DB.prepare('SELECT body, revision FROM films ORDER BY id').all();
      return json({records:results.map(r=>({...JSON.parse(r.body),_revision:r.revision}))});
    }
    if(url.pathname==='/api/import' && request.method==='POST') {
      const data=await request.json();
      if(!Array.isArray(data.records)||data.records.length>10000||!data.records.every(validate)||new Set(data.records.map(r=>r.id)).size!==data.records.length)return json({error:'記録の形式が正しくありません。'},400);
      let added=0;
      for(let i=0;i<data.records.length;i+=50){
        const results=await env.DB.batch(data.records.slice(i,i+50).map(r=>env.DB.prepare('INSERT OR IGNORE INTO films (id, body, revision) VALUES (?, ?, 1)').bind(r.id,JSON.stringify(clean(r)))));
        added+=results.reduce((n,r)=>n+(r.meta?.changes||0),0);
      }
      return json({added});
    }
    if(url.pathname.startsWith('/api/records/')) {
      const id=decodeURIComponent(url.pathname.slice('/api/records/'.length));const data=await request.json();
      if(!Number.isInteger(data._revision)||data._revision<1)return json({error:'最新の画面を開き直してから編集してください。'},409);
      let result;
      if(request.method==='PUT') {
        if(!validate(data)||data.id!==id)return json({error:'記録の形式が正しくありません。'},400);
        result=await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(clean(data)),id,data._revision).run();
      }else if(request.method==='DELETE') {
        // Soft delete: the record moves to ゴミ箱 (trash) for 30 days.
        result={meta:{changes:await softDelete(env,'record',id,data._revision)?1:0}};
      }else return json({error:'この操作は利用できません。'},405);
      if(result.meta.changes!==1)return json({error:'別の端末で更新されています。この画面を開き直してから編集してください。入力中の感想はコピーして残せます。'},409);
      return json({saved:true});
    }
    return json({error:'見つかりません。'},404);
  }catch(e){return json({error:'同期できませんでした。通信状態を確認してもう一度お試しください。'},503);}
}

const TMDB_HOST='https://api.themoviedb.org/3/';
async function cipherKey(env){return crypto.subtle.importKey('raw',Uint8Array.from(atob(env.TMDB_CONFIG_KEY),c=>c.charCodeAt(0)), 'AES-GCM',false,['encrypt','decrypt']);}
async function storedKey(env){const row=await env.DB.prepare("SELECT body FROM app_settings WHERE name = 'tmdb'").first();if(!row)return '';const data=JSON.parse(row.body);return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:Uint8Array.from(data.iv)},await cipherKey(env),Uint8Array.from(data.data)));}
async function upstream(path,key,params){const target=new URL(TMDB_HOST+path);target.searchParams.set('language','ja-JP');for(const [k,v] of params)if(['query','region','include_adult','include_video','page','watch_region','with_watch_providers','with_watch_monetization_types','sort_by','append_to_response','with_release_type','release_date.gte','release_date.lte','with_genres','without_genres','with_original_language','first_air_date.gte','first_air_date.lte','air_date.gte','air_date.lte'].includes(k)&&v.length<=300)target.searchParams.set(k,v);const headers={accept:'application/json'};if(/^[a-f0-9]{32}$/i.test(key))target.searchParams.set('api_key',key);else headers.Authorization='Bearer '+key;return fetch(target,{headers,signal:AbortSignal.timeout(15000)});}
// Calendar arithmetic uses the Tokyo calendar date, independent of server timezone.
function japanWeek(now = new Date()) {
 const today = new Date(now.toLocaleDateString('en-CA', {timeZone:'Asia/Tokyo'}) + 'T00:00:00Z');
 const monday = new Date(today);
 monday.setUTCDate(today.getUTCDate() - (today.getUTCDay() + 6) % 7);
 const sunday = new Date(monday);
 sunday.setUTCDate(monday.getUTCDate() + 6);
 return {start:monday.toISOString().slice(0,10),end:sunday.toISOString().slice(0,10)};
}
async function tmdb(request,env){
 const url=new URL(request.url);
 try{
  if(!env.DB||!env.TMDB_CONFIG_KEY)return json({error:'共通接続を準備しています。'},503);
  if(url.pathname==='/api/tmdb/connection'){
   if(request.method==='GET')return json({connected:!!(await storedKey(env))});
   if(request.method!=='POST'||request.headers.get('Origin')!==url.origin||!request.headers.get('Content-Type')?.startsWith('application/json'))return json({error:'この画面から操作してください。'},403);
   const data=await request.json();const key=typeof data.credential==='string'?data.credential.trim():'';
   if(!key||key.length>4096)return json({error:'接続キーを確認してください。'},400);
   const check=await upstream('configuration',key,[]);if(!check.ok)return json({error:'TMDBの接続キーを確認してください。'},400);
   const iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},await cipherKey(env),new TextEncoder().encode(key));
   await env.DB.prepare("INSERT INTO app_settings(name,body) VALUES('tmdb',?) ON CONFLICT(name) DO UPDATE SET body=excluded.body").bind(JSON.stringify({iv:[...iv],data:[...new Uint8Array(encrypted)]})).run();return json({connected:true});
  }
  if(request.method!=='GET')return json({error:'利用できません。'},405);
  let path=url.pathname.slice('/api/tmdb/'.length);
  let params=url.searchParams;
  if(path==='catalog/week'){
   const week=japanWeek();
   path='discover/movie';
   params=new URLSearchParams({page:params.get('page')||'1',region:'JP',with_release_type:'3|2','release_date.gte':week.start,'release_date.lte':week.end,sort_by:'release_date.asc',include_adult:'false',include_video:'false'});
  }
  if(!/^(configuration|search\/(?:movie|tv)|discover\/(?:movie|tv)|search\/person|person\/[1-9]\d*|movie\/now_playing|trending\/(?:movie|tv)\/week|watch\/providers\/(?:movie|tv)|(?:movie|tv)\/[1-9]\d*(?:\/watch\/providers)?)$/.test(path))return json({error:'見つかりません。'},404);
  const key=await storedKey(env);if(!key)return json({error:'映画情報を接続してください。'},503);
  const result=await upstream(path,key,params);if(!result.ok)return json({error:result.status===429?'検索が混み合っています。少し待って再度お試しください。':'映画情報を取得できませんでした。'},result.status===429?429:502);
  return json(await result.json());
 }catch{return json({error:'映画情報に接続できませんでした。時間をおいて再度お試しください。'},503);}
}

const HTML="<!doctype html>\n<html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#304d40\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-title\" content=\"余韻\"><link rel=\"manifest\" href=\"manifest.webmanifest\"><link rel=\"apple-touch-icon\" href=\"icon-192.png\"><title>余韻 — 私の作品記録</title>\n<style>\n:root{font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif;color:#272b29;background:#f5f4ef}*{box-sizing:border-box}body{margin:0}header{border-bottom:1px solid #dddfd7;padding:24px 6%;display:flex;align-items:center;justify-content:space-between}h1{font-family:serif;font-size:29px;margin:0}small,.muted{color:#747971}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #d6d9ce;background:transparent;padding:10px 16px;border-radius:7px;color:inherit}button.primary{background:#304d40;color:white;border-color:#304d40}main{max-width:1120px;margin:auto;padding:52px 24px}h2{font-family:serif;font-size:36px;font-weight:500;margin:10px 0 18px}.intro{display:flex;justify-content:space-between;align-items:center;gap:24px}.eyebrow{font-size:11px;letter-spacing:3px;color:#68786c}.stats{display:flex;gap:28px;margin:30px 0 40px}.stats b{font-size:28px;font-weight:500;margin-right:7px}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:24px}.toolbar input{margin-left:auto;min-width:160px}.toolbar .active{background:#304d40;color:white}input,textarea,select{border:1px solid #d6d9ce;border-radius:6px;background:#fffefa;padding:11px;color:#272b29}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.card{background:#fffefa;border:1px solid #dedfd6;border-radius:10px;overflow:hidden}.cover{height:160px;background:linear-gradient(135deg,#344e44,#829081);color:#f4efda;display:flex;align-items:center;justify-content:center;font-family:serif;font-size:42px;letter-spacing:8px}.body{padding:20px}.body h3{margin:9px 0;font-size:20px}.badge{font-size:11px;color:#69756b}.rating{color:#ad803b;letter-spacing:2px}.review{white-space:pre-wrap;line-height:1.8;font-size:14px;overflow-wrap:anywhere}.empty{grid-column:1/-1;text-align:center;border:1px dashed #c9cec2;padding:65px 20px;border-radius:10px}.empty p{color:#747971;font-size:14px;line-height:1.9}footer{margin-top:45px;color:#747971;font-size:12px;line-height:1.9}footer button{font-size:12px;margin:10px 5px 0 0}dialog{border:1px solid #d6d9ce;border-radius:14px;padding:28px;width:min(550px,94vw);background:#f9f8f3}dialog::backdrop{background:#14291dc0}form{display:grid;gap:16px}label{display:grid;gap:7px;font-size:13px}.row{display:flex;gap:12px}.row>*{flex:1}.actions{display:flex;justify-content:flex-end;gap:8px}textarea{resize:vertical;min-height:110px}#notice{color:#80552b;font-size:13px} @media(max-width:700px){main{padding:30px 18px}.grid{grid-template-columns:1fr}.intro{align-items:flex-start}h2{font-size:27px}.intro button{white-space:nowrap;padding:10px}.toolbar input{width:100%;margin:0}.stats{gap:18px}header{padding:20px}header small{font-size:10px}.cover{height:130px}}\n\n@media(max-width:700px){input,select,textarea{font-size:16px;min-width:0}label{min-width:0}.row{flex-wrap:wrap}.row>*{flex-basis:125px}dialog{max-height:90dvh;overflow:auto;padding:22px 18px}main{padding-bottom:calc(30px + env(safe-area-inset-bottom))}.intro{flex-wrap:wrap}.stats{font-size:12px}.stats b{font-size:25px}button{min-height:44px}.toolbar{gap:7px}.intro>button{width:100%}}.install{background:#e9ede5;padding:16px 20px;border-radius:8px;margin:20px 0;font-size:13px;line-height:1.8}.install summary{cursor:pointer;font-weight:600}#app-status{font-size:12px;color:#68786c}\n\n.cover.poster{height:300px;letter-spacing:0;overflow:hidden;background:#dce1d6}.cover img{width:100%;height:100%;object-fit:contain}.movie-info{border-top:1px solid #e1e3d9;padding-top:12px;margin:12px 0;font-size:13px;line-height:1.8}.movie-info p{margin:7px 0}.movie-info summary{cursor:pointer}.providers{background:#eef1e9;padding:12px;border-radius:7px;margin:10px 0}.providers b{display:block}.provider-row{margin:6px 0}.pill{display:inline-block;font-size:11px;border:1px solid #d7dfce;padding:2px 7px;margin:2px;border-radius:20px;background:#fffefa}.source{font-size:11px;color:#70796d}.movie-info a,footer a,#connection a{color:#304d40}.lookup{border:1px solid #d6d9ce;padding:15px;border-radius:8px}.lookup-head{display:flex;gap:8px;align-items:center;justify-content:space-between}.lookup-head strong{font-size:13px}.lookup-results{max-height:340px;overflow:auto}.result{display:flex;gap:12px;width:100%;text-align:left;margin:8px 0;background:#fffefa}.result img{width:52px;height:78px;object-fit:cover}.result span{display:block}.result small{display:block;line-height:1.6}.result strong{font-size:14px}.lookup-note{font-size:12px;line-height:1.8;color:#677260;margin:8px 0}#lookup-status,#connection-status{font-size:13px;line-height:1.8}#lookup-preview{font-size:13px;line-height:1.8}.checkbox{display:flex;align-items:center;gap:8px;line-height:1.8}.checkbox input{width:18px;height:18px}.credit{margin-top:20px;padding-top:15px;border-top:1px solid #dddfd7}.credit img{width:90px;display:block;margin-bottom:8px}#connect{font-size:12px}.pending{color:#8a5d2c}@media(max-width:700px){.cover.poster{height:300px}.lookup-head{flex-wrap:wrap}.lookup-head button{width:100%}}\n\n.grid{align-items:start}.cover.poster{height:auto;aspect-ratio:2/3}.cover img{object-fit:cover}.enrich-tools{margin:20px 0;padding:18px;background:#e9ede5;border-radius:10px}.enrich-tools p{font-size:13px;line-height:1.7}.card details.movie-details>summary{cursor:pointer;font-size:13px;color:#304d40;padding:10px 0}.card .body>small{display:block;overflow-wrap:anywhere}.review-needed{color:#885b24;font-size:12px}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:700px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.body{padding:12px}.body h3{font-size:16px}.card .body>small{font-size:11px}.card button{font-size:12px;padding:8px}.card .cover.poster{height:auto;aspect-ratio:2/3}}\n</style><link rel=\"stylesheet\" href=\"explore.css?v=8\"><link rel=\"stylesheet\" href=\"features.css?v=3\"><link rel=\"stylesheet\" href=\"themes.css?v=1\"><script>try{var b=localStorage.getItem(\"yoin-bg\");if(b===\"curtain\"||b===\"screen\"){document.documentElement.dataset.bg=b;document.documentElement.dataset.dark=\"1\";}}catch(e){}</script>\n<header><h1>余韻<span style=\"font:12px sans-serif;margin-left:15px;color:#747971\">映画・アニメ・ドラマの記録</span></h1><button id=\"connect\">映画情報を接続</button></header>\n<main><div class=\"intro\"><div><span class=\"eyebrow\">A LIFE WITH FILMS</span><h2>観た作品を、私の言葉で。</h2><p class=\"muted\">忘れたくないシーンも、まだ観ぬ一本も。</p></div><button class=\"primary\" id=\"add\">＋ 作品を記録</button></div>\n<details class=\"install\" id=\"install-guide\"><summary>iPhoneのホーム画面に追加する</summary><p>① このページをSafariで開く<br>② 共有メニューから「ホーム画面に追加」を選ぶ<br>③ ホーム画面の「余韻」を開いてから記録を始めてください。</p><p>同じChatGPTアカウントでログインすると、MacとiPhoneで共通の記録を使えます。</p></details><p id=\"app-status\" role=\"status\">共通の映画棚に接続しています…</p><nav class=\"main-tabs\" aria-label=\"メイン\"><button id=\"tab-explore\" aria-pressed=\"false\">作品を探す</button><button id=\"tab-library\" aria-pressed=\"true\" class=\"active\">私の作品棚</button><button id=\"tab-lists\" aria-pressed=\"false\">リスト</button><button id=\"tab-stats\" aria-pressed=\"false\">統計</button><button id=\"tab-notices\" aria-pressed=\"false\">お知らせ<span id=\"notice-badge\" class=\"count-badge\" hidden></span></button></nav>\n<section id=\"explore\" hidden>\n  <div class=\"section-heading\"><div><span class=\"eyebrow\">FIND YOUR NEXT FILM</span><h2>次に観たい、一本へ。</h2></div><button id=\"explore-connect\">無料接続を設定</button></div>\n  <form id=\"explore-search-form\" class=\"explore-search\"><input id=\"explore-query\" aria-label=\"作品名\" placeholder=\"作品名・原題から探す（映画・アニメ・ドラマ）\"><button class=\"primary\">検索</button></form>\n  <div class=\"explore-filters\">\n    <label>作品の一覧<select id=\"explore-mode\"><optgroup label=\"映画\"><option value=\"popular\">TMDBで人気の映画</option><option value=\"now\">上映中</option><option value=\"week\">今週公開</option><option value=\"trending\">トレンド（映画）</option></optgroup><optgroup label=\"アニメ・ドラマ\"><option value=\"anime-now\">放送中のアニメ</option><option value=\"anime\">人気のアニメ</option><option value=\"drama\">人気のドラマ</option><option value=\"tv-trending\">トレンド（アニメ・ドラマ）</option><option value=\"tv-popular\">人気のアニメ・ドラマ</option></optgroup></select></label>\n    <label>日本の配信サービス<select id=\"explore-provider\"><option value=\"\">すべて</option></select></label>\n    <label>視聴方法<select id=\"explore-monetization\"><option value=\"flatrate\">見放題</option><option value=\"rent\">レンタル</option><option value=\"buy\">購入</option><option value=\"free\">無料</option><option value=\"ads\">広告付き</option></select></label>\n  </div>\n  <p id=\"explore-status\" role=\"status\" class=\"lookup-note\"></p><div class=\"catalog\" id=\"explore-grid\"></div>\n  <div class=\"pagination\"><button id=\"explore-prev\" hidden>前のページ</button><button id=\"explore-next\" hidden>次のページ</button></div>\n</section><section id=\"library\">\n<div class=\"stats\" id=\"stats\"></div><div class=\"enrich-tools\"><button id=\"enrich-start\">映画棚にポスター・映画情報を追加</button><button id=\"review-filter\">作品の確認が必要な記録</button><p id=\"enrich-status\" role=\"status\">作品名・製作年を照合し、判断できない作品は紐づけずに残します。評価・感想は変更しません。</p></div><div class=\"toolbar\"><button data-filter=\"all\" class=\"active\">すべて</button><button data-filter=\"watched\">鑑賞済み</button><button data-filter=\"want\">観たい</button><button data-filter=\"nodate\" id=\"nodate-filter\">観た日が未入力</button><input id=\"search\" aria-label=\"記録を検索\" placeholder=\"タイトル・感想を検索\"><select id=\"sort\" aria-label=\"並び順\"><option value=\"updated\">登録・更新順</option><option value=\"date\">鑑賞日順</option><option value=\"rating\">評価順</option></select></div><p id=\"notice\" role=\"status\"></p><section class=\"grid\" id=\"grid\"></section>\n</section>\n<section id=\"lists\" hidden><div class=\"section-heading\"><div><span class=\"eyebrow\">MY LISTS</span><h2>私だけのリスト</h2></div><button class=\"primary\" id=\"list-new\">＋ 新しいリスト</button></div><p class=\"lookup-note\">ベスト10やテーマ別など、棚の作品を好きな順に並べられます。作品カードの「リスト」からも追加できます。</p><div id=\"lists-view\"></div></section>\n<section id=\"stats-view\" hidden><div class=\"section-heading\"><div><span class=\"eyebrow\">STATISTICS</span><h2>鑑賞の記録を、数字で。</h2></div></div><div id=\"stats-content\"></div></section>\n<section id=\"notices\" hidden><div class=\"section-heading\"><div><span class=\"eyebrow\">NOTICES</span><h2>お知らせ</h2></div><div class=\"notice-actions\"><button id=\"notices-read-all\">すべて既読</button><button id=\"notices-check\">今すぐ確認</button></div></div><p id=\"notices-status\" class=\"lookup-note\" role=\"status\"></p><div id=\"notices-list\"></div></section>\n<footer>記録は本人専用の保存先へ同期されます。同じChatGPTアカウントでSafari・iPhoneから利用できます。<br>通信が必要です。念のためバックアップも保存できます。<br><button id=\"export\">↓ バックアップを書き出す</button><button id=\"import\">↑ バックアップを読み込む</button><input type=\"file\" id=\"file\" accept=\"application/json,.json\" hidden><button id=\"open-trash\">ゴミ箱</button><button id=\"open-backups\">自動バックアップ</button><div class=\"credit\"><a href=\"https://www.themoviedb.org/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"tmdb-logo.svg\" alt=\"TMDB\"></a>This product uses the TMDB API but is not endorsed or certified by TMDB.<br>作品情報・画像：TMDB ／ 配信情報：<a href=\"https://www.justwatch.com/jp\" target=\"_blank\" rel=\"noopener noreferrer\">JustWatch</a>（TMDB経由）<br>配信先・料金・見放題の対象は変わります。視聴前に配信サービスで確認してください。</div></footer></main>\n<dialog id=\"modal\"><form id=\"form\"><h2 style=\"font-size:25px;margin:0\">作品の記録</h2><input type=\"hidden\" id=\"recordId\"><label>作品名<input id=\"title\" required maxlength=\"200\" placeholder=\"作品のタイトル\"></label><section class=\"lookup\"><div class=\"lookup-head\"><strong>作品情報・日本の配信サービス</strong><button type=\"button\" id=\"lookup\">作品名で検索</button></div><p class=\"lookup-note\">候補から作品を選ぶと公開情報・ポスター・配信情報を反映します。感想は送信しません。</p><p id=\"lookup-status\" role=\"status\"></p><div id=\"lookup-results\" class=\"lookup-results\"></div><div id=\"lookup-preview\"></div></section><div class=\"row\"><label>ステータス<select id=\"status\"><option value=\"watched\">鑑賞済み</option><option value=\"want\">観たい</option></select></label><label>評価<select id=\"rating\"><option value=\"0\">未評価</option><option value=\"0.1\">★ 0.1</option><option value=\"0.2\">★ 0.2</option><option value=\"0.3\">★ 0.3</option><option value=\"0.4\">★ 0.4</option><option value=\"0.5\">★ 0.5</option><option value=\"0.6\">★ 0.6</option><option value=\"0.7\">★ 0.7</option><option value=\"0.8\">★ 0.8</option><option value=\"0.9\">★ 0.9</option><option value=\"1\">★ 1.0</option><option value=\"1.1\">★ 1.1</option><option value=\"1.2\">★ 1.2</option><option value=\"1.3\">★ 1.3</option><option value=\"1.4\">★ 1.4</option><option value=\"1.5\">★ 1.5</option><option value=\"1.6\">★ 1.6</option><option value=\"1.7\">★ 1.7</option><option value=\"1.8\">★ 1.8</option><option value=\"1.9\">★ 1.9</option><option value=\"2\">★ 2.0</option><option value=\"2.1\">★ 2.1</option><option value=\"2.2\">★ 2.2</option><option value=\"2.3\">★ 2.3</option><option value=\"2.4\">★ 2.4</option><option value=\"2.5\">★ 2.5</option><option value=\"2.6\">★ 2.6</option><option value=\"2.7\">★ 2.7</option><option value=\"2.8\">★ 2.8</option><option value=\"2.9\">★ 2.9</option><option value=\"3\">★ 3.0</option><option value=\"3.1\">★ 3.1</option><option value=\"3.2\">★ 3.2</option><option value=\"3.3\">★ 3.3</option><option value=\"3.4\">★ 3.4</option><option value=\"3.5\">★ 3.5</option><option value=\"3.6\">★ 3.6</option><option value=\"3.7\">★ 3.7</option><option value=\"3.8\">★ 3.8</option><option value=\"3.9\">★ 3.9</option><option value=\"4\">★ 4.0</option><option value=\"4.1\">★ 4.1</option><option value=\"4.2\">★ 4.2</option><option value=\"4.3\">★ 4.3</option><option value=\"4.4\">★ 4.4</option><option value=\"4.5\">★ 4.5</option><option value=\"4.6\">★ 4.6</option><option value=\"4.7\">★ 4.7</option><option value=\"4.8\">★ 4.8</option><option value=\"4.9\">★ 4.9</option><option value=\"5\">★ 5.0</option></select></label></div><div class=\"row\"><label>鑑賞日<input type=\"date\" id=\"date\"><span id=\"date-partial-fields\" class=\"partial-fields\" hidden><input id=\"date-y\" type=\"number\" inputmode=\"numeric\" min=\"1900\" max=\"2100\" placeholder=\"年\"><select id=\"date-m\" aria-label=\"月\"><option value=\"\">月不明</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option><option>7</option><option>8</option><option>9</option><option>10</option><option>11</option><option>12</option></select></span><span class=\"checkbox small-check\"><input type=\"checkbox\" id=\"date-partial\">年・月だけ入力</span></label><label>監督・公開年など<input id=\"meta\" maxlength=\"200\" placeholder=\"自由にメモ\"></label></div><div class=\"row\"><label>鑑賞方法<select id=\"method\"><option value=\"\">未設定</option><option value=\"theater\">劇場</option><option value=\"streaming\">配信</option><option value=\"tv\">TV</option><option value=\"disc\">DVD・BD</option><option value=\"other\">その他</option></select></label><label id=\"service-field\">配信サービス<input id=\"service\" maxlength=\"100\" list=\"service-options\" placeholder=\"Netflix など\"></label></div><datalist id=\"service-options\"><option value=\"Netflix\"><option value=\"Amazon Prime Video\"><option value=\"U-NEXT\"><option value=\"Disney+\"><option value=\"Hulu\"><option value=\"ABEMA\"><option value=\"Apple TV+\"><option value=\"dアニメストア\"><option value=\"Lemino\"><option value=\"TELASA\"><option value=\"FOD\"><option value=\"DMM TV\"></datalist><div id=\"viewings-editor\"></div><label>感想・メモ<textarea id=\"review\" maxlength=\"20000\" placeholder=\"この映画を観て、何を感じた？\"></textarea></label><label class=\"checkbox\"><input type=\"checkbox\" id=\"spoiler\">感想にネタバレを含む（タップするまで隠します）</label><div class=\"actions\"><button type=\"button\" id=\"cancel\">キャンセル</button><button class=\"primary\">保存する</button></div></form></dialog>\n<dialog id=\"film-detail\"><div class=\"actions\"><button id=\"film-close\">閉じる</button></div><div id=\"film-content\"></div><p id=\"film-status\" role=\"status\" class=\"lookup-note\"></p><div class=\"actions film-actions\"><button id=\"film-want\">＋ 観たい</button><button id=\"film-record\" class=\"primary\">鑑賞を記録</button></div></dialog>\n<dialog id=\"connection\"><form id=\"connection-form\"><h2 style=\"font-size:25px;margin:0\">映画情報の無料接続</h2><p style=\"font-size:13px;line-height:1.9;margin:0\">TMDBの無料アカウントで映画情報と日本の配信情報を取得します。個人・非商用利用は無料です。</p><ol style=\"font-size:13px;line-height:2;padding-left:20px;margin:0\"><li><a href=\"https://www.themoviedb.org/signup\" target=\"_blank\" rel=\"noopener noreferrer\">TMDBの無料アカウントを作成</a></li><li><a href=\"https://www.themoviedb.org/settings/api\" target=\"_blank\" rel=\"noopener noreferrer\">設定 → API</a>から個人利用のキーを申請（Macでの操作を推奨）</li><li>APIキーまたは「API Read Access Token」を下に貼り付ける</li></ol><label>接続キー<input type=\"password\" id=\"credential\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" required placeholder=\"この画面だけで入力\"></label><input type=\"checkbox\" id=\"remember\" hidden><p class=\"lookup-note\">キーは本人専用の保存先に暗号化して保存します。一度接続すれば、同じアカウントのSafari・iPhoneで入力せず使えます。TMDBへ送るのは作品名・作品IDなどの検索条件だけです。評価や感想、接続キーはバックアップに含めません。</p><p id=\"connection-status\" role=\"status\"></p><div class=\"actions\"><button type=\"button\" id=\"disconnect\">接続について</button><button type=\"button\" id=\"connection-cancel\">閉じる</button><button class=\"primary\" id=\"connection-save\">接続する</button></div></form></dialog><dialog id=\"person-dialog\"><div class=\"actions\"><button id=\"person-close\">閉じる</button></div><div id=\"person-content\"></div><p id=\"person-status\" role=\"status\" class=\"lookup-note\"></p></dialog>\n<dialog id=\"rewatch-dialog\"><form id=\"rewatch-form\"><h2 style=\"font-size:23px;margin:0\">再鑑賞を記録</h2><p id=\"rewatch-title\" class=\"muted\" style=\"margin:0\"></p><div class=\"row\"><label>鑑賞日<input type=\"date\" id=\"rw-date\"></label><label>鑑賞方法<select id=\"rw-method\"><option value=\"\">未設定</option><option value=\"theater\">劇場</option><option value=\"streaming\">配信</option><option value=\"tv\">TV</option><option value=\"disc\">DVD・BD</option><option value=\"other\">その他</option></select></label></div><label id=\"rw-service-field\">配信サービス<input id=\"rw-service\" maxlength=\"100\" list=\"service-options\" placeholder=\"Netflix など\"></label><label>今回の評価<select id=\"rw-rating\"></select></label><p class=\"lookup-note\" style=\"margin:0\">評価を付けると、作品の★もこの評価に更新します。付けなければ今の★のままです。</p><label>今回のメモ<textarea id=\"rw-note\" maxlength=\"5000\" placeholder=\"2回目に気づいたこと\"></textarea></label><div class=\"actions\"><button type=\"button\" id=\"rw-cancel\">キャンセル</button><button class=\"primary\">記録する</button></div></form></dialog>\n<dialog id=\"list-pick\"><h2 style=\"font-size:23px;margin:0 0 6px\">リストに追加</h2><p id=\"list-pick-title\" class=\"muted\"></p><div id=\"list-pick-options\" class=\"pick-options\"></div><div class=\"actions\"><button id=\"list-pick-new\">＋ 新しいリストを作って追加</button><button id=\"list-pick-close\">閉じる</button></div></dialog>\n<dialog id=\"list-edit\"><form id=\"list-edit-form\"><h2 id=\"list-edit-heading\" style=\"font-size:23px;margin:0\">新しいリスト</h2><label>リスト名<input id=\"list-name\" required maxlength=\"100\" placeholder=\"例：生涯ベスト10\"></label><label>説明<textarea id=\"list-description\" maxlength=\"2000\" placeholder=\"どんなリスト？（任意）\" style=\"min-height:70px\"></textarea></label><div class=\"actions\"><button type=\"button\" id=\"list-edit-cancel\">キャンセル</button><button class=\"primary\">保存する</button></div></form></dialog>\n<dialog id=\"list-add\"><h2 style=\"font-size:23px;margin:0 0 10px\">作品を追加</h2><input id=\"list-add-query\" placeholder=\"棚の作品を検索\" style=\"width:100%\"><div id=\"list-add-results\" class=\"pick-options\"></div><div class=\"actions\"><button id=\"list-add-close\">閉じる</button></div></dialog>\n<dialog id=\"trash-dialog\"><div class=\"actions\"><button id=\"trash-close\">閉じる</button></div><h2 style=\"font-size:23px;margin:0\">ゴミ箱</h2><p class=\"lookup-note\">削除した記録・リストは30日間ここに残り、元に戻せます。30日を過ぎると自動で完全に削除されます。</p><p id=\"trash-status\" class=\"lookup-note\" role=\"status\"></p><div id=\"trash-list\" class=\"pick-options\"></div></dialog>\n<dialog id=\"backups-dialog\"><div class=\"actions\"><button id=\"backups-close\">閉じる</button></div><h2 style=\"font-size:23px;margin:0\">自動バックアップ</h2><p class=\"lookup-note\">記録・リスト・再鑑賞・お知らせ・ゴミ箱など全データを、週に1回自動でCloudflareの保存先（D1）にバックアップし、新しい8回分を残します。ダウンロードしたファイルは「↑ バックアップを読み込む」で記録を戻せます。</p><p id=\"backups-status\" class=\"lookup-note\" role=\"status\"></p><div id=\"backups-list\" class=\"pick-options\"></div><div class=\"actions\"><button class=\"primary\" id=\"backup-now\">今すぐバックアップ</button></div></dialog>\n<script src=\"films-api.js?v=8\"></script><script src=\"app.js?v=10\"></script><script src=\"explore.js?v=10\"></script><script src=\"enrichment.js?v=8\"></script><script src=\"features.js?v=2\"></script><script src=\"safety.js?v=1\"></script><script src=\"sheet.js?v=1\"></script><script src=\"theme.js?v=1\"></script></html>\n";
